import csv, math, os
paths={'iron':'tmp/ora/iron_results.tsv','succ':'tmp/ora/succ_results.tsv'}
sig={}
allids={}
for name,path in paths.items():
    rows=list(csv.DictReader(open(path), delimiter='\\t'))
    allids[name]={r['pathway_id'] for r in rows}
    sig[name]={r['pathway_id'] for r in rows if float(r['adjusted_p_value']) < 0.05}
    print(name, 'rows', len(rows), 'sig', len(sig[name]))
    print('sig ids', ','.join(sorted(sig[name])))
only=sig['iron']-sig['succ']
print('only count', len(only))
print('only ids', ','.join(sorted(only)))
# Save diagnostics
os.makedirs('run_trace/final', exist_ok=True)
open('run_trace/final/significant_pathways.txt','w').write('iron_sig\\t%s\\n%s\\nsucc_sig\\t%s\\n%s\\nonly_count\\t%s\\n%s\\n' % (len(sig['iron']), ','.join(sorted(sig['iron'])), len(sig['succ']), ','.join(sorted(sig['succ'])), len(only), ','.join(sorted(only))))
PY"
